    "notes.noteSearchEnabled": "노트 검색 활성화",
    "tray.enabled": "트레이 아이콘으로 백그라운드에서 실행",
    "tray.help": "기본적으로 켜져 있습니다. 창을 닫으면 백그라운드에서 계속 실행됩니다. Smart Sync 트레이 아이콘을 클릭하여 복원하거나 메뉴를 사용하여 다른 볼트가 계속 실행되는 동안 이 볼트를 닫습니다. 로그인 시 실행은 별도의 설정입니다.",
    "startup.enabled": "로그인 시 트레이로 실행",
    "startup.help": "Windows 전용; 기본적으로 꺼져 있습니다. 이 볼트를 열고 기존 동기화 설정을 사용하여 로그인 시 트레이에 숨깁니다. 활성화하면 배경 트레이도 켜집니다. 수동 실행은 계속 표시됩니다.",
