    "msg_df7eea58c8": "로그아웃되었습니다. 로컬 메모는 유지됩니다. 클라우드 장치 승인이 비활성 상태인지 확인할 수 없습니다. 즉시 비활성화가 필요한 경우 연결된 다른 장치에서 비활성화하십시오.",
    "msg_cfbe09811a": "저장 및 기록 정책",
    "msg_94eddf4cf3": "현재 사용된 볼트: {bytes} · 사용된 계정: {accountBytes} / {maximumStoredBytes}.",
    "storage.logicalHelp": "저장소는 현재 파일의 원래 크기를 계산합니다. 기록과 휴지통은 할당량에 포함되지 않습니다. 이전 볼트는 회계가 완료된 후 사용량을 표시합니다.",
