    "msg_9c322a261c": "보존 정책이 저장되었습니다. 기존 기록은 후속 커밋 또는 명시적 정리를 통해 정리됩니다.",
    "msg_d929d25d4b": "현재 콘텐츠 참조: {liveReferencedBytes}; 역사: {historyOnlyBytes}; 참조되지 않음: {orphanBytes}; 보류 중인 업로드: {pendingBytes}. 객체 크기에는 암호화/압축 오버헤드가 포함되며 OSS 청구서가 아닙니다.",
    "msg_17a1d5cfb3": "이러한 작업은 현재 클라우드 볼트만 정리합니다. 현재 메모와 첨부 파일은 유지됩니다. 삭제된 기록은 복원할 수 없습니다.",
    "msg_7aa0c09163": "확인하려면 작업공간 ID를 입력하세요.",
