    "msg_4fd4a230ed": "{revisions} 개정판과 {objects} 사용되지 않은 암호문 개체를 제거했습니다.",
    "msg_edb7cc572e": "로컬 필터 사전 설정",
    "msg_ebc860842a": "사전 설정에는 이 장치의 제외, 연결 임계값 및 구성 범위만 포함됩니다. 키, 노트북 바인딩 및 플러그인 활성화 목록은 포함되지 않습니다. 적용하면 동기화가 일시 중지됩니다.",
