    "account.eraseWarning": "이렇게 하면 계정, 모든 클라우드 노트북, 기록 및 장치 인증이 영구적으로 삭제됩니다. 원래 로그인 키는 즉시 무효화됩니다. 서비스를 다시 이용하려면 새 키를 신청하세요. 로컬 메모가 남아 있습니다.",
    "msg_b3588ca8a2": "계정을 삭제하고 원래 로그인 키를 무효화하려면 “계정 삭제”를 입력하세요.",
    "msg_85ffefa0e5": "계정 및 클라우드 기록이 삭제되었습니다. 원래 로그인 키가 유효하지 않습니다. 서비스를 다시 이용하려면 새 키를 신청하세요. 지역 메모는 그대로 유지됩니다. 스토리지 중단 후 객체 정리를 다시 시도할 수 있습니다.",
