    "msg_6dc05b92e9": "동기화 기록",
    "msg_b9909135b2": "Vault 연결: 로그인 → 선택 → 동기화",
    "msg_44527e0e27": "기존 계정으로 로그인하거나 새 장치를 페어링하세요. 볼트와 범위를 선택한 다음 먼저 변경 사항을 동기화하거나 미리 보세요.",
    "msg_b9c3ee7c9e": "로그인하거나 계정을 요청하세요",
    "msg_2c7acec995": "다른 장치와 페어링",
    "msg_b8ba8e75b9": "클라우드 볼트 선택",
    "msg_f33adfb467": "첫 번째 동기화 미리보기",
    "msg_170f59f23f": "첨부파일 다운로드 기본 설정이 저장되었습니다. 구성 선택이 유지됩니다. 동기화가 일시 중지되었습니다. 재개하기 전에 영향을 미리 확인하세요.",
    "msg_d06a85ea95": "항목별로 구성 항목 동기화",
    "msg_3c63d8d3d6": "명시적으로 선택한 항목만 동기화됩니다. 플러그인 설정에는 연결 정보가 포함될 수 있습니다. 선택하기 전에 검토하세요. 충돌하는 수신 설정은 복사본으로 보존됩니다. 알 수 없는 구조는 병합되지 않습니다. 범위 변경 후 영향을 미리 봅니다.",
    "msg_d6e5b68ca0": "플러그인 코드",
    "msg_b1bc554af4": "플러그인 설정",
