    "msg_fb895c45fc": "대기 중인 동기화 변경사항",
    "msg_1b4e8dcd88": "검토를 위해 {length} 변경 사항이 보류 중입니다. 파일을 실행하기 전까지는 파일이 변경되지 않습니다.",
    "msg_b3866f2fe4": "(요청 시 첨부 파일 다운로드)",
    "msg_ab3252fcee": "변경사항 동기화",
    "msg_2f351d9f91": "변경 없이 취소",
    "msg_849f5c8be8": "수정된 진단 보고서(로컬에서 생성됨)",
    "msg_1300264f75": "보고서에는 버전, 익명 작업 식별자, 결과, 오류 범주 및 통계가 포함됩니다. 노트 내용, 파일 이름, 이메일, 서비스 주소 및 자격 증명은 제외됩니다. 지원팀과 공유하기 전에 검토하세요. 자동으로 업로드되거나 저장소에 기록되지 않습니다.",
    "msg_4ec67f60a5": "복사할 보고서 텍스트를 선택하세요. 이 창을 닫아도 파일이 저장되지 않습니다.",
    "msg_b3e0fd2c33": "먼저 동기화 계획을 검토하고 확인하세요.",
    "msg_3ce8632e0d": "동기화가 일시중지되었습니다. 다시 시도하기 전에 동기화 방향을 선택하세요.",
    "msg_6ca31e24a5": "일부 작업이 실행되지 않았습니다. 동기화 방향, 제외, 이름이 변경된 파일을 확인한 후 다시 시도하세요. 이전의 실패 기록이 유지됩니다.",
    "msg_f59132e78d": "일부 작업이 완료되지 않았습니다. 작업 패널에서 해당 방향, 제외 및 파일 상태를 확인하세요.",
    "msg_06cee02649": "선택한 작업을 다시 시도했습니다. 선택되지 않은 변경사항이 아직 동기화 대기 중입니다.",
    "msg_1202d86812": "최근 500개의 수정된 레코드만 로컬에 보관됩니다. 파일 이름은 현재 세션에만 나타납니다. 다운로드는 필요한 이전 변경 사항을 먼저 수신합니다. 재시도는 충돌을 보존합니다.",
    "msg_fe4f8e3ea3": "작업 기록을 저장할 수 없습니다. 로컬 저장소를 확인하세요. 현재 레코드는 메모리에 남아 있습니다.",
