    "literal:Your paid period ended. Manage your subscription to continue.": "유료 기간이 종료되었습니다. 계속하려면 구독을 관리하세요.",
    "literal:All vaults share this account’s capacity. Manage automatic renewal and cancellation in billing.": "모든 볼트는 이 계정의 용량을 공유합니다. 청구서에서 자동 갱신 및 취소를 관리합니다.",
