    "sorting.folderDatesHelp": "Bei der Erstellung wird der früheste Erstellungszeitpunkt der untergeordneten Datei verwendet. Bei der Änderung wird gemäß den oben genannten Regeln die aktuellste Zeit der untergeordneten Datei verwendet, einschließlich der Unterordner. Leere Ordner folgen veralteten Elementen; Gleiche Daten, Sortierung nach Namen aufsteigend. Dateien enthalten Notizen und Anhänge.",
