    "attachment.onNoteOpen": "Beim Öffnen einer Notiz herunterladen",
    "attachment.help": "Gilt nur für Anhänge wie Bilder, Dokumente und Videos. Notiztext wird immer synchronisiert. Immer herunterladen ruft alle Anhänge ab; Wenn Sie beim Öffnen einer Notiz herunterladen, werden die referenzierten Anhänge abgerufen und vorhandene Kopien bleiben erhalten. Maximale Dateigröße: 256 MB.",
    "preset.help": "Wählen Sie Anhänge zum automatischen Herunterladen aus. Maximale Dateigröße: 256 MB. Sehen Sie sich die Auswirkungen nach dem Ändern dieser Einstellung in der Vorschau an.",
