    "preset.customTitle": "Benutzerdefiniertes Download-Limit für Anhänge",
    "scope.help": "Durch die Aktivierung kann dieses Gerät das Element synchronisieren. Das andere Gerät muss es ebenfalls auswählen und die Synchronisierungsrichtung muss den Empfang ermöglichen. Pause, Ausschlüsse und Bestätigung der Massenlöschung gelten weiterhin. Aktivieren Sie neu empfangene Drittanbieter-Plugins manuell auf diesem Gerät.",
    "core.explain": "Ermöglicht die Synchronisierung der Kern-Plugin-Schalter anderer Geräte, einschließlich Tagesnotizen, Vorlagen und Diagrammansicht. Dadurch können bestehende Schalter verändert werden. Wählen Sie einzelne Core-Plugin-Einstellungen separat aus.",
