    "conflict.binary": "Eine Datei fehlt, binär oder größer als 64 KB. Verwenden Sie zum Vergleich ein geeignetes Tool. Die Originaldateien bleiben unverändert.",
    "conflict.resolved": "Konflikt gelöst. Wenn Sie lokale Inhalte ausgewählt haben, synchronisieren Sie diese mit der Cloud.",
    "msg_6dc05b92e9": "Verlauf synchronisieren",
    "msg_b9909135b2": "Einen Tresor verbinden: Anmelden → Auswählen → Synchronisieren",
    "msg_44527e0e27": "Melden Sie sich mit einem bestehenden Konto an oder koppeln Sie ein neues Gerät. Wählen Sie Ihren Tresor und Bereich aus und synchronisieren Sie dann zunächst die Änderungen oder zeigen Sie eine Vorschau an.",
    "msg_b9c3ee7c9e": "Melden Sie sich an oder fordern Sie ein Konto an",
    "msg_2c7acec995": "Mit einem anderen Gerät koppeln",
    "msg_b8ba8e75b9": "Wählen Sie einen Cloud-Tresor",
    "msg_f33adfb467": "Vorschau der ersten Synchronisierung",
    "msg_170f59f23f": "Einstellungen zum Herunterladen von Anhängen gespeichert. Die Konfigurationsauswahl bleibt erhalten. Die Synchronisierung ist angehalten. Sehen Sie sich die Auswirkungen in einer Vorschau an, bevor Sie fortfahren.",
    "msg_d06a85ea95": "Synchronisieren Sie die Konfiguration Element für Element",
    "msg_3c63d8d3d6": "Nur explizit ausgewählte Elemente werden synchronisiert. Plugin-Einstellungen können Verbindungsinformationen enthalten; Überprüfen Sie es vor der Auswahl. Widersprüchliche empfangene Einstellungen bleiben als Kopien erhalten; Unbekannte Strukturen werden nicht zusammengeführt. Sehen Sie sich die Auswirkungen nach der Änderung des Umfangs in der Vorschau an.",
    "msg_d6e5b68ca0": "Plugin-Code",
    "msg_b1bc554af4": "Plugin-Einstellungen",
