    "msg_49efd10178": "Hochladen (vor der Ausführung erneut überprüft)",
    "msg_6e68458688": "Empfangen",
    "msg_5a787a8fca": "Lokal aktualisieren",
    "msg_005281db0d": "Lokal umziehen",
    "msg_ae10caca31": "In der Cloud umbenennen",
    "msg_d9599ba702": "Lokal löschen",
    "msg_4c079853d0": "Aus der Cloud löschen",
    "msg_848a148ba5": "Konflikte bewahren und lösen",
    "msg_dda3f1ce08": "Überspringen Sie gemäß den aktuellen Regeln",
    "msg_02d4e6c7d7": "Nur Datensätze aktualisieren",
    "msg_fb895c45fc": "Ausstehende Synchronisierungsänderungen",
    "msg_1b4e8dcd88": "{length}, Änderungen stehen zur Überprüfung aus. Es ändern sich keine Dateien, bis Sie sie ausführen.",
    "msg_b3866f2fe4": "(Anhänge können auf Anfrage heruntergeladen werden)",
    "msg_ab3252fcee": "Synchronisieren Sie diese Änderungen",
    "msg_2f351d9f91": "Ohne Änderungen stornieren",
    "msg_849f5c8be8": "Geschwärzter Diagnosebericht (lokal generiert)",
    "msg_1300264f75": "Der Bericht enthält Versionen, anonyme Aufgabenkennungen, Ergebnisse, Fehlerkategorien und Statistiken. Ausgenommen sind Notizinhalte, Dateinamen, E-Mail-Adressen, Dienstadressen und Anmeldeinformationen. Überprüfen Sie es, bevor Sie es mit dem Support teilen. Es wird niemals automatisch hochgeladen oder in Ihren Tresor geschrieben.",
    "msg_4ec67f60a5": "Wählen Sie den Berichtstext aus, um ihn zu kopieren. Durch das Schließen dieses Fensters wird keine Datei gespeichert.",
    "msg_b3e0fd2c33": "Überprüfen und bestätigen Sie zunächst den Synchronisierungsplan.",
    "msg_3ce8632e0d": "Die Synchronisierung ist angehalten. Wählen Sie eine Synchronisierungsrichtung aus, bevor Sie es erneut versuchen.",
    "msg_6ca31e24a5": "Einige Aufgaben wurden nicht ausgeführt. Überprüfen Sie die Synchronisierungsrichtung, Ausschlüsse und umbenannte Dateien und versuchen Sie es dann erneut. Frühere Fehleraufzeichnungen werden aufbewahrt.",
    "msg_f59132e78d": "Einige Aufgaben sind unvollständig. Überprüfen Sie deren Richtung, Ausschlüsse und Dateistatus im Aufgabenbereich.",
    "msg_06cee02649": "Ausgewählte Aufgaben wurden wiederholt. Nicht ausgewählte Änderungen warten noch auf die Synchronisierung.",
    "msg_1202d86812": "Nur die letzten 500 redigierten Datensätze werden lokal gespeichert. Dateinamen werden nur in der aktuellen Sitzung angezeigt. Downloads erhalten zuerst die erforderlichen vorherigen Änderungen. Wiederholungsversuche bewahren Konflikte.",
    "msg_fe4f8e3ea3": "Der Aufgabenverlauf konnte nicht gespeichert werden. Lokalen Speicher prüfen; Aktuelle Datensätze bleiben im Speicher.",
