    "notes.noteSearchEnabled": "Activer la recherche de notes",
    "tray.enabled": "Exécuter en arrière-plan avec l'icône de la barre d'état",
    "tray.help": "Activé par défaut. La fermeture de la fenêtre la maintient en arrière-plan. Cliquez sur l'icône de la barre d'état Smart Sync pour le restaurer ou utilisez son menu pour fermer ce coffre-fort pendant que d'autres coffres-forts continuent de fonctionner. Le lancement à la connexion est un paramètre distinct.",
    "startup.enabled": "Lancer dans la barre d'état lors de la connexion",
    "startup.help": "Windows uniquement ; désactivé par défaut. Ouvrez ce coffre-fort et cachez-le dans la barre d'état lors de la connexion, en utilisant les paramètres de synchronisation existants. L'activation active également la barre d'état arrière-plan. Les lancements manuels restent visibles.",
