    "msg_d929d25d4b": "Références de contenu actuelles : {liveReferencedBytes} ; historique : {historyOnlyBytes} ; non référencé : {orphanBytes} ; téléchargements en attente : {pendingBytes}. La taille des objets inclut la surcharge de chiffrement/compression et ne constitue pas une facture OSS.",
