    "sorting.folderDates": "Dates des dossiers",
    "sorting.folderDatesHelp": "La création utilise la première heure de création du fichier enfant. La modification utilise l'heure du fichier enfant la plus récente selon les règles ci-dessus, y compris les sous-dossiers. Les dossiers vides suivent les éléments datés ; les dates égales sont triées par nom croissant. Les fichiers incluent des notes et des pièces jointes.",
