    "exclusions.help": "Choisissez le contenu du coffre-fort cloud à exclure sur cet appareil. La sélection d'un dossier inclut ses descendants et ne supprime aucun fichier local ou cloud. D'autres appareils utilisent leurs propres paramètres.",
