    "attachment.onNoteOpen": "Télécharger lors de l'ouverture d'une note",
    "attachment.help": "S'applique uniquement aux pièces jointes telles que les images, les documents et les vidéos. Le texte de la note est toujours synchronisé. Toujours télécharger récupère toutes les pièces jointes ; Le téléchargement lors de l'ouverture d'une note récupère ses pièces jointes référencées et conserve les copies existantes. Taille maximale du fichier : 256 MB.",
    "preset.help": "Choisissez les pièces jointes à télécharger automatiquement. Taille maximale du fichier : 256 MB. Prévisualisez l’impact après avoir modifié ce paramètre.",
    "preset.phone": "Petits accessoires uniquement (≤2 MB)",
