    "preset.customTitle": "Limite de téléchargement de pièces jointes personnalisées",
    "scope.help": "L'activation permet à cet appareil de synchroniser l'élément. L'autre appareil doit également le sélectionner et le sens de synchronisation doit permettre la réception. La pause, les exclusions et la confirmation de suppression groupée s'appliquent toujours. Activez manuellement les plugins tiers nouvellement reçus sur cet appareil.",
    "core.explain": "Permet aux commutateurs de plug-in principaux d'autres appareils de se synchroniser ici, y compris les notes quotidiennes, les modèles et la vue graphique. Cela peut modifier les commutateurs existants. Sélectionnez séparément les paramètres individuels du plug-in principal.",
