    "msg_6dc05b92e9": "Historique de synchronisation",
    "msg_b9909135b2": "Connecter un coffre-fort : connectez-vous → sélectionnez → synchroniser",
    "msg_44527e0e27": "Connectez-vous avec un compte existant ou associez un nouvel appareil. Sélectionnez votre coffre-fort et votre étendue, puis synchronisez ou prévisualisez d'abord les modifications.",
