    "msg_f33adfb467": "Aperçu de la première synchronisation",
    "msg_170f59f23f": "Préférences de téléchargement des pièces jointes enregistrées. Les sélections de configuration sont conservées. La synchronisation est suspendue ; prévisualisez l’impact avant de reprendre.",
    "msg_d06a85ea95": "Synchroniser la configuration élément par élément",
    "msg_3c63d8d3d6": "Seuls les éléments explicitement sélectionnés sont synchronisés. Les paramètres du plugin peuvent inclure des informations de connexion ; examiner avant de sélectionner. Les paramètres reçus en conflit sont conservés sous forme de copies ; les structures inconnues ne sont pas fusionnées. Prévisualisez l’impact après avoir modifié la portée.",
