    "msg_fb895c45fc": "Modifications de synchronisation en attente",
    "msg_1b4e8dcd88": "{length} modifications en attente pour examen. Aucun fichier ne change jusqu'à ce que vous les exécutiez.",
    "msg_b3866f2fe4": "(pièces jointes à télécharger sur demande)",
    "msg_ab3252fcee": "Synchronisez ces modifications",
    "msg_2f351d9f91": "Annuler sans modifications",
    "msg_849f5c8be8": "Rapport de diagnostic rédigé (généré localement)",
    "msg_1300264f75": "Le rapport contient des versions, des identifiants de tâches anonymes, des résultats, des catégories d'erreurs et des statistiques. Il exclut le contenu des notes, les noms de fichiers, les e-mails, les adresses de service et les informations d'identification. Vérifiez-le avant de le partager avec l'assistance. Il n’est jamais téléchargé automatiquement ni écrit dans votre coffre-fort.",
    "msg_4ec67f60a5": "Sélectionnez le texte du rapport pour le copier. La fermeture de cette fenêtre n'enregistre pas de fichier.",
    "msg_b3e0fd2c33": "Vérifiez et confirmez d'abord le plan de synchronisation.",
    "msg_3ce8632e0d": "La synchronisation est suspendue. Sélectionnez une direction de synchronisation avant de réessayer.",
    "msg_6ca31e24a5": "Certaines tâches n'ont pas été exécutées. Vérifiez le sens de synchronisation, les exclusions et les fichiers renommés, puis réessayez. Les enregistrements des échecs antérieurs sont conservés.",
    "msg_f59132e78d": "Certaines tâches sont incomplètes. Vérifiez leur direction, leurs exclusions et l'état du fichier dans le panneau des tâches.",
    "msg_06cee02649": "Les tâches sélectionnées ont été réessayées. Les modifications non sélectionnées attendent toujours la synchronisation.",
    "msg_1202d86812": "Seuls les 500 derniers dossiers expurgés sont conservés localement. Les noms de fichiers apparaissent uniquement dans la session en cours. Les téléchargements reçoivent en premier les modifications précédentes requises ; les nouvelles tentatives préservent les conflits.",
    "msg_fe4f8e3ea3": "Impossible de sauvegarder l'historique des tâches. Vérifiez le stockage local ; les enregistrements actuels restent en mémoire.",
