    "msg_170f59f23f": "Preferencias de descarga de archivos adjuntos guardadas. Las selecciones de configuración se mantienen. La sincronización está en pausa; Obtenga una vista previa del impacto antes de continuar.",
    "msg_d06a85ea95": "Sincronizar configuración elemento por elemento",
    "msg_3c63d8d3d6": "Solo se sincronizan los elementos seleccionados explícitamente. La configuración del complemento puede incluir información de conexión; revisar antes de seleccionar. Las configuraciones recibidas en conflicto se conservan como copias; Las estructuras desconocidas no se fusionan. Obtenga una vista previa del impacto después de cambiar el alcance.",
