    "msg_fb895c45fc": "Cambios de sincronización pendientes",
    "msg_1b4e8dcd88": "{length} cambios pendientes para revisión. Ningún archivo cambia hasta que los ejecuta.",
    "msg_b3866f2fe4": "(descarga de archivos adjuntos a pedido)",
    "msg_ab3252fcee": "Sincroniza estos cambios",
    "msg_2f351d9f91": "Cancelar sin cambios",
    "msg_849f5c8be8": "Informe de diagnóstico redactado (generado localmente)",
    "msg_1300264f75": "El informe contiene versiones, identificadores de tareas anónimos, resultados, categorías de errores y estadísticas. Excluye contenidos de notas, nombres de archivos, correo electrónico, direcciones de servicio y credenciales. Revíselo antes de compartirlo con soporte. Nunca se carga automáticamente ni se escribe en su bóveda.",
    "msg_4ec67f60a5": "Seleccione el texto del informe para copiarlo. Cerrar esta ventana no guarda un archivo.",
    "msg_b3e0fd2c33": "Primero revise y confirme el plan de sincronización.",
    "msg_3ce8632e0d": "La sincronización está en pausa. Seleccione una dirección de sincronización antes de volver a intentarlo.",
    "msg_6ca31e24a5": "Algunas tareas no se ejecutaron. Verifique la dirección de sincronización, las exclusiones y los archivos renombrados, luego vuelva a intentarlo. Se mantienen registros de fallas anteriores.",
    "msg_f59132e78d": "Algunas tareas están incompletas. Verifique su dirección, exclusiones y estado del archivo en el panel de tareas.",
    "msg_06cee02649": "Se reintentaron las tareas seleccionadas. Los cambios no seleccionados aún esperan sincronización.",
    "msg_1202d86812": "Sólo los últimos 500 registros redactados se conservan localmente. Los nombres de los archivos aparecen sólo en la sesión actual. Las descargas reciben primero los cambios anteriores requeridos; Los reintentos preservan los conflictos.",
    "msg_fe4f8e3ea3": "No se pudo guardar el historial de tareas. Verifique el almacenamiento local; Los registros actuales permanecen en la memoria.",
