    "scope.help": "A ativação permite que este dispositivo sincronize o item. O outro dispositivo também deve selecioná-lo e a direção de sincronização deve permitir o recebimento. Pausa, exclusões e confirmação de exclusão em massa ainda se aplicam. Ative manualmente plug-ins de terceiros recém-recebidos neste dispositivo.",
