    "msg_1300264f75": "O relatório contém versões, identificadores anônimos de tarefas, resultados, categorias de erros e estatísticas. Exclui conteúdo de notas, nomes de arquivos, e-mail, endereços de serviço e credenciais. Revise-o antes de compartilhar com o suporte. Ele nunca é carregado automaticamente ou gravado em seu cofre.",
