    "msg_94eddf4cf3": "Текущее используемое хранилище: {bytes} · Используемая учетная запись: {accountBytes} / {maximumStoredBytes}.",
    "storage.logicalHelp": "Хранилище подсчитывает исходный размер текущих файлов. История и мусор не учитываются в квоте. В старых хранилищах использование отображается после завершения учета.",
    "msg_36342cf528": "Сохранение истории",
    "msg_a31f0d5da8": "90 дней, минимум 10 версий",
    "msg_2fff7456f2": "30 дней, минимум 10 версий",
    "msg_7635f2db97": "7 дней, минимум 10 версий",
    "msg_e3fb03d459": "Только текущая версия",
    "msg_494ca78f73": "Пользовательский",
    "msg_51de0850f6": "Дни хранения",
    "msg_9d34177b21": "Минимальное количество сохраненных версий",
    "msg_11b553f933": "Сохранить политику хранения",
    "msg_9c322a261c": "Политика хранения сохранена. Существующая история очищается последующей фиксацией или явной очисткой.",
    "msg_d929d25d4b": "Ссылки на текущий контент: {liveReferencedBytes}; история: {historyOnlyBytes}; без ссылки: {orphanBytes}; ожидающие загрузки: {pendingBytes}. Размеры объектов включают накладные расходы на шифрование/сжатие и не являются расходами OSS.",
    "msg_17a1d5cfb3": "Эти действия очищают только текущее облачное хранилище. Текущие примечания и вложения сохраняются; удаленную историю невозможно восстановить.",
    "msg_7aa0c09163": "Введите идентификатор рабочей области для подтверждения.",
    "msg_d12185b679": "Безвозвратно очистить всю историю удаленных заметок (все страницы)",
    "msg_5280de73c3": "Очищена история удаленных заметок {purgedNotes}; живые заметки и надгробия при удалении сохраняются.",
    "msg_6aa7a7fb4d": "Применяйте сохранение и собирайте неиспользуемые объекты",
    "msg_a58295f5c5": "Сохраняйте только текущие версии и собирайте неиспользуемые объекты.",
    "msg_4fd4a230ed": "Удалены версии {revisions} и неиспользуемые объекты зашифрованного текста {objects}.",
    "msg_edb7cc572e": "Предварительные настройки локального фильтра",
    "msg_ebc860842a": "Предустановки содержат только исключения этого устройства, порог подключения и область конфигурации. Ключи, привязки блокнота и списки включения плагинов не включены. Применение пауз синхронизации.",
    "msg_e283e2fc15": "Применить: {name}",
    "msg_300a2093ce": "Применена локальная предустановка; просмотрите настройки и возобновите работу явно.",
    "msg_3b70db4d79": "Сохранить текущие фильтры в качестве предустановки",
    "msg_afadbad990": "Сохранить локальную предустановку",
    "msg_e534a6662a": "Имя предустановки",
    "msg_246af2bffc": "Предустановка локального фильтра сохранена.",
    "msg_cda8bc73dc": "Безвозвратно стереть облачные данные учетной записи",
    "msg_316ef5f989": "Адрес электронной почты аккаунта",
    "msg_104f734a38": "Ключ входа в учетную запись (не ключ сопряженного устройства)",
    "account.eraseWarning": "При этом учетная запись, все ее облачные записные книжки, история и авторизация устройств будут удалены без возможности восстановления. Исходный ключ входа в систему немедленно становится недействительным. Чтобы снова воспользоваться услугой, подайте заявку на новый ключ. Местные примечания остаются.",
    "msg_b3588ca8a2": "Введите «Удалить учетную запись», чтобы удалить учетную запись и сделать недействительным исходный ключ входа.",
    "msg_85ffefa0e5": "Записи аккаунта и облака удалены. Исходный ключ входа недействителен; подайте заявку на новый ключ, чтобы снова воспользоваться услугой. Местные примечания остаются; очистка объекта может повториться после перебоев в работе хранилища.",
    "msg_98d23d7e0e": "Запросить ключ доступа",
    "msg_f2488fd4ef": "Адрес электронной почты",
    "msg_043fd8bfeb": "Статус заявки: {status}.",
    "msg_8f35919eaf": "Восстановлено устройство Obsidian.",
    "msg_1616ece37e": "Ноутбук подключен с двусторонней синхронизацией. Синхронизируйте сейчас или, при необходимости, сначала просмотрите.",
    "msg_911a5a5fee": "Подключить Smart Sync",
    "msg_6d3f7c7e30": "Зарегистрированные пользователи",
    "msg_bdbdb86464": "Новые пользователи",
    "msg_2f6f0adc32": "Выдан ключ входа",
    "msg_3f56b1794d": "Используйте выданный ключ или пару с другого устройства.",
    "msg_369780c1a6": "Только новым пользователям необходимо подать заявку на получение ключа.",
    "msg_bcd99fecff": "Продолжить с ключом",
