    "msg_a152f8d825": "Введите свой ключ для входа.",
    "msg_280f46b896": "Введите свой адрес электронной почты.",
    "msg_0f5179405d": "Заявление отправлено. Оператор должен утвердить ваш ключ и отправить его по электронной почте; затем вернитесь к зарегистрированным пользователям.",
    "msg_1b5cc18c43": "Подтвердите подключение к ноутбуку",
    "msg_55e27d0828": "Разблокируйте и подтвердите этот блокнот",
    "msg_4647ca53a9": "Создать новый зашифрованный блокнот",
