    "msg_4e9bfa704d": "Имя блокнота",
    "msg_6064779aa9": "Новая парольная фраза для шифрования ноутбука (минимум 12 символов)",
    "msg_8e60cde0d2": "Этот ключ недействителен или отозван. Проверьте его или запросите замену.",
    "msg_4e5ad8c798": "Проверьте введенный адрес электронной почты.",
    "msg_9b1d6b4113": "Дозвониться до сервиса не удалось. Проверьте адрес службы и повторите попытку.",
    "msg_a070395fba": "Сопряжение с помощью шестизначного кода",
