    "msg_0ce5c19b92": "Сравнить проверку общего секрета",
    "msg_b2054ece22": "Проверка: {verification}. Перед применением сравните это с существующим устройством. Код должен точно совпадать.",
    "msg_2c21cae1e2": "Я сравнил оба устройства и проверки совпадают",
