    "msg_3dda76845a": "Доступ к устройству отозван. Загруженные локальные файлы остаются на этом устройстве.",
    "msg_4014ed1760": "Защитите резервную копию конфигурации",
    "msg_d8ad61a613": "Отдельный резервный пароль (минимум 12 символов)",
    "msg_db6716f3a2": "Зашифрованный текст восстановления",
    "msg_e6c1993381": "Скопируйте и сохраните этот зашифрованный текст вне блокнота.",
