    "msg_3e39703b6e": "Резервный пароль",
    "msg_bb170489f7": "Необязательный новый ключ входа в систему, если резервный ключ устройства был отозван.",
    "msg_f833981bdb": "Подтвердить восстановленное рабочее пространство",
    "msg_b9070a5af5": "Восстановите соединение с ноутбуком из этой резервной копии. Настройки подключения управляются системой; синхронизация остается приостановленной после импорта.",
    "msg_61b792d4de": "Примените эту восстановленную конфигурацию",
