    "msg_22ab7d735f": "Вложение скачано.",
    "msg_3b18c9eb76": "Удалить локальную копию: {path}.",
    "msg_0bd1ef30b4": "Локальная копия удалена с использованием ваших предпочтений удаления. Привязка к облаку сохраняется.",
