    "msg_7628eb97f7": "Версия {sequence}; {length}. При этом создается новая облачная версия и сохраняются конфликтующие локальные изменения.",
    "msg_227ddcef1b": "Бинарный файл; перед восстановлением проверьте версию и размер.",
