    "notebooks.deleteHelp": "Безвозвратно удаляет облачные заметки, вложения, историю и мусор из этого хранилища, а также останавливает синхронизацию этого хранилища на всех устройствах. Ваша учетная запись, ключ входа, другие хранилища и локальные заметки сохраняются. Срок действия независимых автономных резервных копий истекает в соответствии с существующей политикой хранения. Это невозможно отменить.",
