    "lan.title": "LAN-ускорение",
    "lan.help": "Устройства в одной локальной сети предпочитают прямую зашифрованную передачу и автоматически возвращаются в облако. Облачные резервные копии и история изменений остаются доступными. Никакой настройки адреса не требуется.",
