    "sorting.mtime-desc": "Модифицированный нисходящий (сначала самые новые)",
    "sorting.folderDates": "Даты папок",
    "sorting.folderDatesHelp": "При создании используется самое раннее время создания дочернего файла. Модификация использует самое последнее время дочернего файла в соответствии с приведенными выше правилами, включая подпапки. Пустые папки следуют за датированными элементами; равные даты сортируются по имени по возрастанию. Файлы включают примечания и вложения.",
