    "sections.disconnected": "Никакая учетная запись не подключена. Войдите в систему или выполните сопряжение с существующим устройством.",
    "exclusions.title": "Выберите файлы и папки, которые нужно исключить из синхронизации.",
    "exclusions.help": "Выберите содержимое облачного хранилища, которое нужно исключить на этом устройстве. Выбор папки включает ее потомков и не удаляет локальные или облачные файлы. Другие устройства используют свои собственные настройки.",
    "exclusions.loading": "Чтение облачных папок без загрузки содержимого заметок или вложений…",
