    "attachment.always": "Всегда скачивать (по умолчанию)",
    "attachment.onNoteOpen": "Загрузка при открытии заметки",
    "attachment.help": "Применяется только к вложениям, таким как изображения, документы и видео. Текст заметки всегда синхронизируется. При загрузке всегда извлекаются все вложения; При загрузке при открытии заметки извлекаются вложения, на которые имеются ссылки, и сохраняются существующие копии. Максимальный размер файла: 256 MB.",
    "preset.help": "Выберите вложения для автоматической загрузки. Максимальный размер файла: 256 MB. Предварительно просмотрите влияние после изменения этого параметра.",
    "preset.phone": "Только небольшие насадки (≤2 MB)",
    "preset.tablet": "Общие вложения (≤8 MB)",
