    "preset.custom": "Нестандартный размер…",
    "preset.customTitle": "Ограничение на загрузку пользовательских вложений",
    "scope.help": "Включение позволяет этому устройству синхронизировать элемент. Другое устройство также должно выбрать его, а направление синхронизации должно разрешать прием. Приостановка, исключения и подтверждение массового удаления по-прежнему применяются. Вручную включите вновь полученные сторонние плагины на этом устройстве.",
    "core.explain": "Позволяет синхронизировать переключатели основных плагинов других устройств, включая ежедневные заметки, шаблоны и представление графика. Это может изменить существующие переключатели. Выберите отдельные настройки ядра-плагина отдельно.",
    "core.enable": "Подтвердить включение",
    "core.cancel": "Отменить; оставить отключенным",
    "core.saved": "Синхронизация переключателя ядра-плагина включена. Выберите одну и ту же область на обоих устройствах, при необходимости просмотрите результат и проверьте результат после перезапуска Obsidian.",
