    "plan.counts": "Проверьте загрузки {uploads}; {downloads} получает/обновляет; {moves} перемещается; Удаление {deletes}; {conflicts} конфликтует.",
    "plan.next": "Показать больше запланированных изменений",
    "plan.paused": "Синхронизация приостановлена. Эта предварительная версия предполагает двустороннюю синхронизацию. Подтверждение включает двустороннюю синхронизацию; отмена ставит его на паузу.",
    "diagnostic.save": "Сохраните отредактированный диагностический отчет локально.",
