    "conflict.remote": "Текущая версия",
    "conflict.binary": "Файл отсутствует, является двоичным или имеет размер более 64 KB. Используйте соответствующий инструмент для сравнения. Исходные файлы не изменяются.",
    "conflict.resolved": "Конфликт разрешен. Если вы выбрали локальный контент, синхронизируйте его с облаком.",
    "msg_6dc05b92e9": "Синхронизировать историю",
    "msg_b9909135b2": "Подключите хранилище: войдите → выберите → синхронизировать.",
    "msg_44527e0e27": "Войдите в систему с помощью существующей учетной записи или подключите новое устройство. Выберите хранилище и область действия, а затем сначала синхронизируйте или просмотрите изменения.",
    "msg_b9c3ee7c9e": "Войдите или запросите учетную запись",
    "msg_2c7acec995": "Сопряжение с другим устройством",
    "msg_b8ba8e75b9": "Выберите облачное хранилище",
    "msg_f33adfb467": "Предварительный просмотр первой синхронизации",
    "msg_170f59f23f": "Настройки загрузки вложений сохранены. Выбор конфигурации сохраняется. Синхронизация приостановлена; просмотрите результат перед возобновлением.",
    "msg_d06a85ea95": "Синхронизировать конфигурацию поэлементно",
    "msg_3c63d8d3d6": "Синхронизируются только явно выбранные элементы. Настройки плагина могут включать информацию о соединении; просмотрите перед выбором. Конфликтующие полученные настройки сохраняются в виде копий; неизвестные структуры не объединяются. Предварительный просмотр эффекта после изменения области действия.",
