    "msg_02d4e6c7d7": "Обновлять только записи",
    "msg_fb895c45fc": "Ожидаемые изменения синхронизации",
    "msg_1b4e8dcd88": "{length} ожидает внесения изменений на проверку. Никакие файлы не изменяются, пока вы их не запустите.",
    "msg_b3866f2fe4": "(приложения скачиваются по запросу)",
    "msg_ab3252fcee": "Синхронизировать эти изменения",
    "msg_2f351d9f91": "Отменить без изменений",
    "msg_849f5c8be8": "Отредактированный диагностический отчет (созданный локально)",
    "msg_1300264f75": "Отчет содержит версии, идентификаторы анонимных задач, результаты, категории ошибок и статистику. Сюда не входит содержимое заметок, имена файлов, адрес электронной почты, адреса служб и учетные данные. Просмотрите его, прежде чем поделиться со службой поддержки. Он никогда не загружается автоматически и не записывается в ваше хранилище.",
    "msg_4ec67f60a5": "Выделите текст отчета, чтобы скопировать его. Закрытие этого окна не сохраняет файл.",
    "msg_b3e0fd2c33": "Сначала просмотрите и подтвердите план синхронизации.",
    "msg_3ce8632e0d": "Синхронизация приостановлена. Прежде чем повторить попытку, выберите направление синхронизации.",
    "msg_6ca31e24a5": "Некоторые задачи не запускались. Проверьте направление синхронизации, исключения и переименованные файлы, затем повторите попытку. Записи о более ранних отказах сохраняются.",
    "msg_f59132e78d": "Некоторые задачи не выполнены. Проверьте их направление, исключения и состояние файлов на панели задач.",
    "msg_06cee02649": "Выбранные задачи повторены. Невыбранные изменения все еще ожидают синхронизации.",
    "msg_1202d86812": "Только последние 500 отредактированных записей хранятся локально. Имена файлов отображаются только в текущем сеансе. Загрузки сначала получают необходимые предыдущие изменения; повторные попытки сохраняют конфликты.",
    "msg_fe4f8e3ea3": "Не удалось сохранить историю задач. Проверьте локальное хранилище; текущие записи остаются в памяти.",
    "msg_5c55a67935": "Все",
