    "msg_42e67eb3e4": "Очистить историю",
    "msg_b4391a4866": "Дни хранения сервера, ограничения на записи и подробные сведения управляются администратором. Отчеты {value0} ожидают доставки. В автономной очереди хранятся самые новые результаты, вплоть до 2000.",
