    "msg_5d00b2a3a1": "Только загрузить",
    "msg_8d2013c20f": "Получать только",
    "msg_c8b249e6e2": "Обновлять только существующие файлы",
    "msg_d871435514": "Подключите учетную запись или новое устройство",
    "msg_9145d92358": "Сначала войдите в систему или выполните сопряжение, а затем выберите хранилище. Новые подключения остаются приостановленными.",
    "msg_fd2d01b08e": "Просмотр ожидающих изменений синхронизации",
    "msg_d1b456ced0": "Просмотрите загрузки, получения, перемещения и удаления, чтобы выявить проблемы с синхронизацией. Большие хранилища могут занять время.",
